public:
    TreeNode* reverseOddLevels(TreeNode* root) {
        queue<TreeNode*> q;
        q.push(root);
        int x = 1,n,i,z;
        vector<TreeNode*> tmp;
        TreeNode* node;
        // undefinedNode is no longer needed/used correctly, but we keep structure. 
        // We will just not use it or ensure the branch uses 'node'.
        while(!q.empty()){
            tmp.clear();
            n = q.size();
            while(n--){
                node = q.front();q.pop();
                if(x==0){
                    tmp.push_back(node); // Fixed: was undefinedNode
                }
                if(node->left)
                    q.push(node->left);
                if(node->right){
                    q.push(node->right);
                }
            }
            n = tmp.size();
            for(i = 0; i < n/2; i++){ // Fixed: was <= n/2, which causes double swapping
                z = tmp[i]->val;
                tmp[i]->val = tmp[n-1-i]->val;
                tmp[n-1-i]->val = z; // Fixed: was "z; syntax error
            }
            x ^= 1;
            n = 0;
        }
        return root;
    }
};
